insert into public.gyms (name, city, state, country, cc, brand, latitude, longitude, status, grading_style)
select name, city, state, country, cc, brand, latitude, longitude, status, grading_style
from incoming i
where not exists (
  select 1
  from public.gyms g
  where lower(regexp_replace(g.name, '[^a-z0-9]+', '', 'g')) = i.normalized_name
    and (
      (g.latitude is not null and g.longitude is not null
        and abs(g.latitude - i.latitude) < 0.0015
        and abs(g.longitude - i.longitude) < 0.0015)
      or (
        lower(coalesce(g.city, '')) = lower(coalesce(i.city, ''))
        and lower(coalesce(g.country, '')) = lower(i.country)
      )
    )
);

